import{bQ as i,aL as a,u as t,G as h}from"./chunks/framework.D06dwy5q.js";const g=JSON.parse('{"title":"04｜hash、list、set、zset","description":"","frontmatter":{},"headers":[],"relativePath":"05.Redis/04-hash-list-set-zset.md","filePath":"05.Redis/04-hash-list-set-zset.md","lastUpdated":null}'),e={name:"05.Redis/04-hash-list-set-zset.md"};function n(l,s,p,k,d,r){return a(),t("div",null,[...s[0]||(s[0]=[h(`<h1 id="_04-hash、list、set、zset" tabindex="-1">04｜hash、list、set、zset <a class="header-anchor" href="#_04-hash、list、set、zset" aria-label="Permalink to &quot;04｜hash、list、set、zset&quot;">​</a></h1><p>string 只能存一个值对应一个 key。但很多数据天然是&quot;一个对象多个属性&quot;——用户有 name/age/city、文章有 title/author/views、商品有 name/price/stock。先用 string 方案试一下，再讲 Redis 另外四种数据结构各自解决什么问题。</p><h2 id="一、hash-一个对象多个属性" tabindex="-1">一、hash：一个对象多个属性 <a class="header-anchor" href="#一、hash-一个对象多个属性" aria-label="Permalink to &quot;一、hash：一个对象多个属性&quot;">​</a></h2><p>用 string 存一个用户的三个属性：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001:name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;zhangsan&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001:age</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;28&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001:city</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;beijing&quot;</span></span></code></pre></div><p>存是能存，但取的时候麻烦。要拿到这个用户的完整信息，得 GET 三次：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001:name</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001:age</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001:city</span></span></code></pre></div><p>三个 key 分布在键空间里，改一个属性要操作一个 key，不影响其他属性这件事得靠应用层保证。key 数量也翻了几倍——一万个用户，string 方案要三万个 key。</p><p>hash 把同一个对象的所有属性收进一个 key 里：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HSET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;zhangsan&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> age</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;28&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> city</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;beijing&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HGET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># &quot;zhangsan&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HGETALL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># name zhangsan</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># age 28</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># city beijing</span></span></code></pre></div><p><code>HGETALL</code> 一次命令拿回所有 field-value，不用往返三次。改 <code>city</code> 只动那一个 field，其他不动。</p><p>常用命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HSET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;zhangsan&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 设单个 field</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HGET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # 取单个</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HDEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> city</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # 删某个 field</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HEXISTS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # field 是否存在</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HINCRBY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> age</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # 某个数字 field 自增</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HLEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                            # 有多少个 field</span></span></code></pre></div><p><code>HINCRBY</code> 在 hash 上也能原子自增——存访问量这种数字属性时，不需要取出再写回。</p><h3 id="hgetall-在大-hash-上慢" tabindex="-1">HGETALL 在大 hash 上慢 <a class="header-anchor" href="#hgetall-在大-hash-上慢" aria-label="Permalink to &quot;HGETALL 在大 hash 上慢&quot;">​</a></h3><p><code>HGETALL</code> 的复杂度是 O(n)，n 是 field 数量。几百个 field 没问题，几千个就要用 <code>HSCAN</code> 分批取：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HSCAN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> COUNT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span></code></pre></div><p>生产里 <code>HGETALL</code> 上慢日志，最常见的原因就是 field 数量超预期。</p><p>另一个更隐蔽的点：hash 在 field 少时用压缩编码（ziplist），内存很省；field 数量超过阈值（默认 512）或单个值超过 64 字节后转成 hashtable 编码，内存会跳涨。一个存了几百个短 field 的 hash 突然翻倍涨内存，多半是触发了编码转换。阈值由 <code>hash-max-ziplist-entries</code> 和 <code>hash-max-ziplist-value</code> 控制。</p><h2 id="二、list-有序可重复的序列" tabindex="-1">二、list：有序可重复的序列 <a class="header-anchor" href="#二、list-有序可重复的序列" aria-label="Permalink to &quot;二、list：有序可重复的序列&quot;">​</a></h2><p>用 string 做消息队列行不通——没有&quot;取出一条消息同时把它从队列里删掉&quot;的原子操作。应用层 <code>GET</code> 再 <code>DEL</code> 是两步，中间可能插进别的客户端，同一条消息被两个消费者同时拿到。</p><p>list 是双向链表，首尾插入和删除都是 O(1)，天然适合存有序序列：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LPUSH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;task1&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 左侧（队头）插入</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LPUSH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;task2&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RPUSH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;task3&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 右侧（队尾）插入</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LRANGE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 看全部：task2 task1 task3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LPOP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # 从队头取</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RPOP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # 从队尾取</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LLEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # 长度</span></span></code></pre></div><p><code>LPUSH</code> + <code>RPOP</code> 组合做 FIFO 队列——先入先出。<code>BLPOP</code>/<code>BRPOP</code> 支持阻塞等待：队列为空时消费者挂起，有新元素立刻返回，应用层不用轮询空转：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BLPOP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 阻塞等队列有元素，0 表示无限等待</span></span></code></pre></div><p>list 消费消息有个局限：消息 <code>RPOP</code> 出去就消失了——消费者处理到一半崩溃，消息就丢了。需要 ACK 机制、消费者组、消息持久化的队列场景，要用 Redis 5.0 引入的 Stream。Stream 比 list 多了消费者组、消息 ID 和 ACK 机制，专门为消息队列设计。</p><h2 id="三、set-无序不重复的集合" tabindex="-1">三、set：无序不重复的集合 <a class="header-anchor" href="#三、set-无序不重复的集合" aria-label="Permalink to &quot;三、set：无序不重复的集合&quot;">​</a></h2><p>用 string 存文章的标签，每个标签一个 key：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> article:1:tag1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;redis&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> article:1:tag2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;database&quot;</span></span></code></pre></div><p>去重困难——同一个标签被重复写入，应用层得自己检查。算&quot;两篇文章的共同标签&quot;更麻烦，所有标签拉回应用层再算交集。</p><p>set 元素不重复，增删查都是 O(1)：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SADD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> article:1:tags</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;redis&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;database&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;nosql&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SISMEMBER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> article:1:tags</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;redis&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 是否存在</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SMEMBERS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> article:1:tags</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # 取所有成员</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SCARD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> article:1:tags</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 元素个数</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SREM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> article:1:tags</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;nosql&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 删成员</span></span></code></pre></div><p>真正有用的是集合运算：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SINTER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> article:1:tags</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> article:2:tags</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 交集：共同标签</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SUNION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> article:1:tags</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> article:2:tags</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 并集：所有标签</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SDIFF</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:1:friends</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:2:friends</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 差集：user1 有但 user2 没有的好友</span></span></code></pre></div><p>经典场景：社交关系的&quot;共同好友&quot;——<code>SINTER user:1001:friends user:1002:friends</code> 一条命令算出来。</p><p>但要注意数据量。<code>SINTER</code>/<code>SUNION</code>/<code>SDIFF</code> 的复杂度是 O(n)，n 是参与运算的所有元素总数。两个集合各几十万人，这一条命令会阻塞 Redis 数秒，其他请求全排队。大数据量的集合运算应该在从库或离线环境跑，别在主库上算。</p><h2 id="四、zset-带分数的有序集合" tabindex="-1">四、zset：带分数的有序集合 <a class="header-anchor" href="#四、zset-带分数的有序集合" aria-label="Permalink to &quot;四、zset：带分数的有序集合&quot;">​</a></h2><p>用 string 做排行榜，每次更新分数要走三步：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> player1_score</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 取出当前分数</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 应用层加 5、排序</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> player1_score</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 105</span></span></code></pre></div><p>多客户端同时更新时，跟 INCR 的竞态条件一样——覆盖丢失。更麻烦的是排序，string 里存的是孤立数值，Redis 不知道谁大谁小，排一次序要遍历所有 key。</p><p>zset（sorted set）每个元素关联一个 score（浮点数），插入时自动按 score 排序：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ZADD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> leaderboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;player1&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 95</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;player2&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 88</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;player3&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ZRANGE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> leaderboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WITHSCORES</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 按 score 升序</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ZREVRANGE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> leaderboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WITHSCORES</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 前 3 名（降序）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ZREVRANK</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> leaderboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;player1&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # player1 排第几（从 0 开始）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ZSCORE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> leaderboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;player1&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # 查 player1 的分数</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ZINCRBY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> leaderboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;player1&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 加 5 分</span></span></code></pre></div><p>插入或更新分数是 O(log n)，查排名也快——千万级用户的排行榜也能响应。</p><p>zset 的其他用途：</p><p><strong>带权重的任务队列</strong>——score 存优先级，按优先级取任务。</p><p><strong>延迟队列</strong>——score 存&quot;应该被处理的时间戳&quot;，消费者用 <code>ZRANGEBYSCORE</code> 取出到期的任务：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ZRANGEBYSCORE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delay_queue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%s)&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span></span></code></pre></div><p>处理完 <code>ZREM</code> 删除。但延迟队列同样没 ACK——消费者崩溃任务就丢。生产延迟队列用专门的消息中间件更稳妥。</p><h2 id="五、五种类型怎么选" tabindex="-1">五、五种类型怎么选 <a class="header-anchor" href="#五、五种类型怎么选" aria-label="Permalink to &quot;五、五种类型怎么选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要存什么</th><th>用什么</th><th>为什么</th></tr></thead><tbody><tr><td>单值缓存、计数器</td><td>string</td><td>单值场景最直接</td></tr><tr><td>一个对象的多个属性</td><td>hash</td><td>一个 key 装多个 field，省 key 数、查对象一次往返</td></tr><tr><td>消息序列、最近 N 条</td><td>list</td><td>有序、可重复、首尾操作快</td></tr><tr><td>去重、标签、共同关系</td><td>set</td><td>不重复、集合运算</td></tr><tr><td>排行榜、按分数取</td><td>zset</td><td>自动排序、按区间取</td></tr></tbody></table><p>选错能跑通但性能差几个数量级。用 string 存排行榜：每次更新要 <code>GET</code> 取值、应用层排序、再 <code>SET</code> 回去——多往返、非原子、慢。用 zset 存同一批数据，一条 <code>ZADD</code> 或 <code>ZINCRBY</code> 就够了。</p><h2 id="六、其他类型" tabindex="-1">六、其他类型 <a class="header-anchor" href="#六、其他类型" aria-label="Permalink to &quot;六、其他类型&quot;">​</a></h2><p>除了这五种，Redis 后续版本加了一些专门类型：</p><ul><li><strong>Stream</strong>：带消费者组、消息 ID、ACK 机制的消息队列，比 list 当队列可靠</li><li><strong>Geospatial</strong>：地理位置索引，算距离、范围查询</li><li><strong>HyperLogLog</strong>：基数估算，UV 这种&quot;去重计数&quot;用很少内存</li><li><strong>Bitmap</strong>：位操作，存布尔状态、做位统计</li></ul><p>这些用得没有五大类型多，用到时查文档，本系列主线讲五大类型。</p>`,55)])])}const o=i(e,[["render",n]]);export{g as __pageData,o as default};
